/* ==== INTERFACE ====
方向：瑞士国际主义（Swiss Style）。依托清晰的对齐轴、冷白底色、高反差无衬线字阶与直角结构线，以鲜明的国际克莱因红与纯黑为核心视觉焦点，适用于微观经济学供求模型、弹性代数公式与制度边界解析。
reference style:02-swiss
token --bg：页面底色（#fbfbfb 清爽冷白底）。
token --text：正文色（#111111 纯黑）。
token --muted：次要说明与标注文字（#6b7280 沉稳冷灰）。
token --accent：主强调色（#e63917 瑞士国际红，用于关键断点、斜线标记与重点量）。
token --focus：焦点环高亮色（#111111）。
token --font-sans：正文及通用无衬线字体（NTF-inter, NTF-noto-sans-sc, sans-serif）。
token --font-display：标题与重要大字排印（NTF-barlow-condensed, NTF-noto-sans-sc, sans-serif）。
class .nt-title：普通页题名（font-size: 40px; font-weight: 800; line-height: 1.1; display: block）。
class .nt-title-hero：封面/章节大字强调（font-size: 76px; font-weight: 800; line-height: 0.96; letter-spacing: -0.02em; text-transform: uppercase）。
class .nt-subtitle：区块副标题/导读（font-size: 20px; font-weight: 500; line-height: 1.4; color: var(--text-sec)）。
class .nt-kicker：栏目分类小标/序号（font-size: 13px; font-weight: 700; letter-spacing: 0.12em; text-transform: uppercase; color: var(--accent)）。
class .nt-grid-line：网格结构线与基准线分割（border-top: 1px solid var(--border) 或 2px solid var(--text)）。
class .nt-colorblock：高对比直角色块容器（默认亮红底白字，可修饰为黑底白字）。
class .nt-rule-accent：瑞士斜线或垂直重音修饰线条（宽 3px，高度自适应，纯红实体）。
class .nt-chart-axis / .nt-chart-grid / .nt-chart-curve：图表通用轴线、网格参考线与供求曲线（供需曲线通过 currentColor 承接）。
class .nt-btn：直角无衬线交互按钮与状态样式。
variant opening：开篇或总览页，背景带有极轻的细密微结构网格线，左侧提供强视觉对齐骨架。
默认：不设 data-variant；纯色冷白底搭配极简结构线。
品牌：无。
==== /INTERFACE ==== */

/* 字体资源声明 */
@font-face {
  font-family: "NTF-noto-sans-sc";
  src: url("fonts/library/noto-sans-sc/face-0.ttf");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-barlow-condensed";
  src: url("fonts/library/barlow-condensed/face-0.ttf");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-barlow-condensed";
  src: url("fonts/library/barlow-condensed/face-1.ttf");
  font-weight: 700;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-barlow-condensed";
  src: url("fonts/library/barlow-condensed/face-2.ttf");
  font-weight: 800;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-inter";
  src: url("fonts/library/inter/face-0.ttf");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-inter";
  src: url("fonts/library/inter/face-1.ttf");
  font-weight: 100 900;
  font-style: italic;
  font-display: swap;
}

/* 基础全局 Token 定义 */
:root {
  /* 色板：高对比国际红、纯黑与洁净冷灰白 */
  --bg: #f8f8f9;
  --bg-subtle: #f0f1f3;
  --text: #121316;
  --text-sec: #4b525d;
  --muted: #828a96;
  --border: #dcdfe4;
  --border-strong: #121316;

  --accent: #e63412;
  --accent-hover: #c92c0d;
  --accent-light: #fef0ed;

  --focus: #121316;
  --focus-ring: rgba(18, 19, 22, 0.2);

  /* 经济学专用语义对比色（供需/无谓损失/控制线），通过变量向图表开放 */
  --color-demand: #1d4ed8;
  --color-supply: #e63412;
  --color-surplus: #10b981;
  --color-deadweight: #f59e0b;

  /* 字体族 */
  --font-display: "NTF-barlow-condensed", "NTF-noto-sans-sc", -apple-system, sans-serif;
  --font-sans: "NTF-inter", "NTF-noto-sans-sc", -apple-system, sans-serif;
  --font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;

  /* 瑞士严谨字阶系统 (基于 1600x900 逻辑画幅) */
  --fs-hero: 76px;
  --fs-h1: 42px;
  --fs-h2: 28px;
  --fs-h3: 22px;
  --fs-lead: 19px;
  --fs-body: 16px;
  --fs-sec: 14px;
  --fs-label: 13px;
  --fs-tick: 12px;

  /* 统一间距与网格系统标尺 */
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 24px;
  --space-6: 32px;
  --space-8: 48px;
  --space-10: 64px;
  --space-12: 80px;

  /* 结构参数：瑞士风格绝对直角与坚实实线 */
  --radius-none: 0px;
  --stroke-thin: 1px;
  --stroke-normal: 1.5px;
  --stroke-thick: 3px;
  --stroke-heavy: 5px;
}

/* 舞台基底设置 */
#stage {
  background-color: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  font-size: var(--fs-body);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  box-sizing: border-box;
}

/* 开篇 / 封面变体：带有精密对齐辅助线底纹 */
html[data-variant="opening"] #stage {
  background-color: var(--bg);
  background-image: 
    linear-gradient(to right, rgba(18, 19, 22, 0.04) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(18, 19, 22, 0.04) 1px, transparent 1px);
  background-size: 80px 80px;
  background-position: 0 0;
}

/* 暗色沉浸/对比变体（如深入剖析市场失灵或税收扭曲深度页） */
html[data-variant="dark"] {
  --bg: #111215;
  --bg-subtle: #1a1c22;
  --text: #f4f5f7;
  --text-sec: #a3abb7;
  --muted: #676f7d;
  --border: #282c35;
  --border-strong: #f4f5f7;
  --accent: #ff4724;
  --accent-hover: #ff5f40;
  --accent-light: rgba(255, 71, 36, 0.15);
  --focus: #ffffff;
  --focus-ring: rgba(255, 255, 255, 0.3);
}

/* 具名排版体系 */
.nt-title-hero {
  font-family: var(--font-display);
  font-size: var(--fs-hero);
  font-weight: 800;
  line-height: 0.94;
  letter-spacing: -0.025em;
  color: var(--text);
  margin: 0;
  text-transform: uppercase;
}

.nt-title-hero:lang(zh) {
  font-family: var(--font-sans);
  font-weight: 900;
  letter-spacing: -0.015em;
  line-height: 1.05;
}

.nt-title {
  font-family: var(--font-sans);
  font-size: var(--fs-h1);
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -0.015em;
  color: var(--text);
  margin: 0;
}

.nt-title:lang(zh) {
  font-weight: 800;
  letter-spacing: -0.01em;
}

.nt-subtitle {
  font-family: var(--font-sans);
  font-size: var(--fs-h3);
  font-weight: 500;
  line-height: 1.4;
  color: var(--text-sec);
  margin: 0;
}

.nt-kicker {
  font-family: var(--font-display);
  font-size: var(--fs-label);
  font-weight: 800;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--accent);
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
}

.nt-kicker:lang(zh) {
  font-family: var(--font-sans);
  font-weight: 700;
  letter-spacing: 0.08em;
}

.nt-lead {
  font-size: var(--fs-lead);
  font-weight: 400;
  line-height: 1.5;
  color: var(--text);
}

.nt-caption {
  font-size: var(--fs-sec);
  line-height: 1.45;
  color: var(--text-sec);
}

.nt-data-num {
  font-family: var(--font-sans);
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.02em;
}

/* 瑞士风色块与分区构件 */
.nt-colorblock {
  background-color: var(--accent);
  color: #ffffff;
  padding: var(--space-6);
  border-radius: var(--radius-none);
  box-sizing: border-box;
  position: relative;
}

.nt-colorblock--black {
  background-color: var(--text);
  color: var(--bg);
}

.nt-colorblock--subtle {
  background-color: var(--bg-subtle);
  color: var(--text);
  border-left: var(--stroke-thick) solid var(--border-strong);
}

/* 规则结构线与重音装饰 */
.nt-grid-line {
  height: 0;
  border: none;
  border-top: var(--stroke-thin) solid var(--border);
  margin: 0;
}

.nt-grid-line--strong {
  border-top: var(--stroke-thick) solid var(--border-strong);
}

.nt-grid-line--accent {
  border-top: var(--stroke-thick) solid var(--accent);
}

.nt-slash-accent {
  display: inline-block;
  width: 4px;
  height: 1.1em;
  background-color: var(--accent);
  transform: skewX(-20deg);
  vertical-align: -0.15em;
  margin: 0 var(--space-2);
}

.nt-pillar-rule {
  width: 1px;
  background-color: var(--border);
  align-self: stretch;
}

/* 假说与适用边界标签 (用于经济学假设前提标注) */
.nt-tag {
  display: inline-flex;
  align-items: center;
  font-size: var(--fs-label);
  font-weight: 600;
  padding: 2px 8px;
  border-radius: var(--radius-none);
  border: 1px solid var(--border-strong);
  background: transparent;
  color: var(--text);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.nt-tag--accent {
  background: var(--accent);
  border-color: var(--accent);
  color: #ffffff;
}

.nt-tag--outline-accent {
  border-color: var(--accent);
  color: var(--accent);
}

/* 代数模型与公式专区样式 */
.nt-math-block {
  font-family: var(--font-mono);
  font-size: var(--fs-h3);
  padding: var(--space-4) var(--space-5);
  background: var(--bg-subtle);
  border-left: var(--stroke-heavy) solid var(--text);
  color: var(--text);
  box-sizing: border-box;
}

/* 供求与弹性分析交互控件（无衬线、硬直角、高可见度） */
.nt-btn {
  appearance: none;
  border: 1.5px solid var(--border-strong);
  background-color: transparent;
  color: var(--text);
  font-family: var(--font-sans);
  font-size: var(--fs-sec);
  font-weight: 700;
  padding: 10px 20px;
  border-radius: var(--radius-none);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  letter-spacing: 0.02em;
  transition: background-color 140ms ease, color 140ms ease, border-color 140ms ease;
}

.nt-btn:hover {
  background-color: var(--text);
  color: var(--bg);
}

.nt-btn:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.nt-btn--accent {
  background-color: var(--accent);
  border-color: var(--accent);
  color: #ffffff;
}

.nt-btn--accent:hover {
  background-color: var(--accent-hover);
  border-color: var(--accent-hover);
  color: #ffffff;
}

.nt-btn[aria-pressed="true"],
.nt-btn--active {
  background-color: var(--text);
  color: var(--bg);
  border-color: var(--text);
}

/* 坐标系与供需模型图解专用标准类 (SVG / Canvas / 节点) */
.nt-chart-axis {
  stroke: var(--text);
  stroke-width: var(--stroke-normal);
}

.nt-chart-grid {
  stroke: var(--border);
  stroke-width: var(--stroke-thin);
  stroke-dasharray: 3 3;
}

.nt-chart-curve {
  fill: none;
  stroke: currentColor;
  stroke-width: var(--stroke-thick);
  stroke-linecap: square;
  stroke-linejoin: miter;
}

.nt-chart-curve--demand {
  stroke: var(--color-demand);
}

.nt-chart-curve--supply {
  stroke: var(--color-supply);
}

.nt-chart-point {
  fill: var(--text);
  stroke: var(--bg);
  stroke-width: 2px;
}

.nt-chart-area {
  fill-opacity: 0.18;
}

.nt-chart-label {
  font-family: var(--font-sans);
  font-size: var(--fs-tick);
  font-weight: 600;
  fill: var(--text-sec);
  dominant-baseline: central;
}

/* 焦点与无障碍尊重 */
@media (prefers-reduced-motion: reduce) {
  .nt-btn {
    transition: none;
  }
}
